7	//===----------------------------------------------------------------------===//
8	//
9	// Utilities for calling / handling wrapper functions that use SPS
10	// serialization.
11	//
12	//===----------------------------------------------------------------------===//
13	
14	#ifndef ORC_RT_SPSWRAPPERFUNCTION_H
15	#define ORC_RT_SPSWRAPPERFUNCTION_H
16	
17	#include "orc-rt/Compiler.h"
18	#include "orc-rt/SimplePackedSerialization.h"
19	#include "orc-rt/WrapperFunction.h"
20	
21	#define ORC_RT_SPS_WRAPPER(Name, SPSSig, Handle)                               \
22	  static void Name(orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes, \
23	                   orc_rt_WrapperFunctionReturn Return, uint64_t CallId) {     \
24	    orc_rt::SPSWrapperFunction<SPSSig>::handle(S, ArgBytes, Return, CallId,    \
25	                                               Handle);                        \
26	  }
27	
28	namespace orc_rt {
29	namespace detail {
30	
31	template <typename... SPSArgTs> struct WFSPSHelper {
32	private:
33	  template <typename... SerializableArgTs>
34	  std::optional<WrapperFunctionBuffer>
35	  serializeImpl(const SerializableArgTs &...Args) {
36	    auto R =
37	        WrapperFunctionBuffer::allocate(SPSArgList<SPSArgTs...>::size(Args...));
38	    SPSOutputBuffer OB(R.data(), R.size());
39	    if (!SPSArgList<SPSArgTs...>::serialize(OB, Args...))
40	      return std::nullopt;
41	    return std::move(R);
42	  }
43	
44	  template <typename T> struct Serializable {
45	    typedef std::decay_t<T> serializable_type;
46	    static const T &to(const T &Arg) noexcept { return Arg; }
47	    static T &&from(T &&Arg) noexcept { return std::forward<T>(Arg); }
48	  };
49	
50	  template <> struct Serializable<Error> {
51	    typedef SPSSerializableError serializable_type;
52	    static SPSSerializableError to(Error Err) {
53	      return SPSSerializableError(std::move(Err));
54	    }
55	    static Error from(SPSSerializableError Err) { return Err.toError(); }
56	  };
57	
58	  template <typename T> struct Serializable<Expected<T>> {
59	    typedef SPSSerializableExpected<T> serializable_type;
60	    static SPSSerializableExpected<T> to(Expected<T> Val) {
61	      return SPSSerializableExpected<T>(std::move(Val));
62	    }
63	    static Expected<T> from(SPSSerializableExpected<T> Val) {
64	      return Val.toExpected();
65	    }
66	  };
67	
68	  template <typename... Ts> struct DeserializableTuple;
69	
70	  template <typename... Ts> struct DeserializableTuple<std::tuple<Ts...>> {
71	    typedef std::tuple<typename Serializable<Ts>::serializable_type...> type;
72	  };
73	
74	  template <typename... Ts>
75	  using DeserializableTuple_t = typename DeserializableTuple<Ts...>::type;
76	
77	  template <typename ArgTuple, typename... SerializableArgs, std::size_t... Is>
78	  std::optional<ArgTuple>
79	  applySerializationConversions(std::tuple<SerializableArgs...> &Inputs,
80	                                std::index_sequence<Is...>) {
81	    static_assert(sizeof...(SerializableArgs) ==
82	                      std::index_sequence<Is...>::size(),
83	                  "Tuple sizes don't match");
84	    return std::optional<ArgTuple>(
85	        std::in_place, Serializable<std::tuple_element_t<Is, ArgTuple>>::from(
86	                           std::move(std::get<Is>(Inputs)))...);
87	  }
88	
89	public:
90	  template <typename... ArgTs>
91	  std::optional<WrapperFunctionBuffer> serialize(ArgTs &&...Args) {
92	    return serializeImpl(
93	        Serializable<std::decay_t<ArgTs>>::to(std::forward<ArgTs>(Args))...);
94	  }
95	
96	  template <typename ArgTuple>
97	  std::optional<ArgTuple> deserialize(const WrapperFunctionBuffer &ArgBytes) {
98	    assert(!ArgBytes.getOutOfBandError() &&
99	           "Should not attempt to deserialize out-of-band error");
100	    SPSInputBuffer IB(ArgBytes.data(), ArgBytes.size());
101	    DeserializableTuple_t<ArgTuple> Args;
102	    if (!SPSSerializationTraits<SPSTuple<SPSArgTs...>,
103	                                decltype(Args)>::deserialize(IB, Args))
104	      return std::nullopt;
105	    return applySerializationConversions<ArgTuple>(
106	        Args, std::make_index_sequence<std::tuple_size_v<ArgTuple>>());
107	  }
108	};
109	
110	} // namespace detail
111	
112	template <typename SPSSig> struct WrapperFunctionSPSSerializer;
113	
114	template <typename SPSRetT, typename... SPSArgTs>
115	struct WrapperFunctionSPSSerializer<SPSRetT(SPSArgTs...)> {
116	  static detail::WFSPSHelper<SPSArgTs...> arguments() noexcept { return {}; }
117	  static detail::WFSPSHelper<SPSRetT> result() noexcept { return {}; }
118	};
119	
120	/// Provides call and handle utilities to simplify writing and invocation of
121	/// wrapper functions that use SimplePackedSerialization to serialize and
122	/// deserialize their arguments and return values.
123	template <typename SPSSig> struct SPSWrapperFunction {
124	  template <typename Caller, typename ResultHandler, typename... ArgTs>
125	  static void call(Caller &&C, ResultHandler &&RH, ArgTs &&...Args) {
126	    WrapperFunction::call(
127	        std::forward<Caller>(C), WrapperFunctionSPSSerializer<SPSSig>(),
128	        std::forward<ResultHandler>(RH), std::forward<ArgTs>(Args)...);
129	  }
130	
131	  template <typename Handler>
132	  static void handle(orc_rt_SessionRef S, WrapperFunctionBuffer ArgBytes,
133	                     orc_rt_WrapperFunctionReturn Return, uint64_t CallId,
134	                     Handler &&H) {
135	    WrapperFunction::handle(S, std::move(ArgBytes), Return, CallId,
136	                            WrapperFunctionSPSSerializer<SPSSig>(),
137	                            std::forward<Handler>(H));
138	  }
139	
140	  /// Convenience override that takes ArgBytes as an
141	  /// orc_rt_WrapperFunctionBuffer.
142	  template <typename Handler>
143	  static void handle(orc_rt_SessionRef S, orc_rt_WrapperFunctionBuffer ArgBytes,
144	                     orc_rt_WrapperFunctionReturn Return, uint64_t CallId,
145	                     Handler &&H) {
146	    handle(S, WrapperFunctionBuffer(ArgBytes), Return, CallId,
147	           std::forward<Handler>(H));
148	  }
149	};
150	
151	} // namespace orc_rt
152	
153	#endif // ORC_RT_SPSWRAPPERFUNCTION_H
