17	#include "orc-rt/WrapperFunction.h"
18	
19	namespace orc_rt {
20	
21	struct SPSWrapperFunctionBuffer;
22	
23	template <>
24	class SPSSerializationTraits<SPSWrapperFunctionBuffer, WrapperFunctionBuffer> {
25	public:
26	  static size_t size(const WrapperFunctionBuffer &WFB) {
27	    return SPSArgList<uint64_t>::size(static_cast<uint64_t>(WFB.size())) +
28	           WFB.size();
29	  }
30	
31	  static bool serialize(SPSOutputBuffer &OB, const WrapperFunctionBuffer &WFB) {
32	    if (!SPSArgList<uint64_t>::serialize(OB, static_cast<uint64_t>(WFB.size())))
33	      return false;
34	    return OB.write(WFB.data(), WFB.size());
35	  }
36	
37	  static bool deserialize(SPSInputBuffer &IB, WrapperFunctionBuffer &WFB) {
38	    uint64_t Size;
39	    if (!SPSArgList<uint64_t>::deserialize(IB, Size))
40	      return false;
41	    WFB = WrapperFunctionBuffer::allocate(Size);
42	    return IB.read(WFB.data(), WFB.size());
43	  }
44	};
45	
46	} // namespace orc_rt
47	
48	#endif // ORC_RT_SPSWRAPPERFUNCTIONBUFFER_H
