22	/// Define an allocation-action wrapper function with the given Name that
23	/// uses SPS to deserialize its arguments and dispatches to Handle.
24	///
25	/// SPSArgs is a parenthesized comma-separated list of SPS argument types
26	/// (the parens are stripped by ORC_RT_DEPAREN before being expanded into
27	/// the SPSAllocActionFunction template instantiation):
28	///
29	///     static Error checkEq(int32_t X, int32_t Y);
30	///     ORC_RT_SPS_ALLOC_ACTION(check_eq_action, (int32_t, int32_t), checkEq)
31	///
32	#define ORC_RT_SPS_ALLOC_ACTION(Name, SPSArgs, Handle)                         \
33	  static orc_rt_WrapperFunctionBuffer Name(const char *ArgData,                \
34	                                           size_t ArgSize) {                   \
35	    return orc_rt::SPSAllocActionFunction<ORC_RT_DEPAREN(SPSArgs)>::handle(    \
36	               ArgData, ArgSize, Handle)                                       \
37	        .release();                                                            \
38	  }
39	
40	namespace orc_rt {
41	
42	struct SPSAllocAction;
43	
44	template <> class SPSSerializationTraits<SPSAllocAction, AllocAction> {
45	public:
46	  static size_t size(const AllocAction &AA) {
47	    return SPSArgList<SPSExecutorAddr, SPSWrapperFunctionBuffer>::size(
48	        ExecutorAddr::fromPtr(AA.Fn), AA.ArgData);
49	  }
50	
51	  static bool serialize(SPSOutputBuffer &OB, const AllocAction &AA) {
52	    return SPSArgList<SPSExecutorAddr, SPSWrapperFunctionBuffer>::serialize(
53	        OB, ExecutorAddr::fromPtr(AA.Fn), AA.ArgData);
54	  }
55	
56	  static bool deserialize(SPSInputBuffer &IB, AllocAction &AA) {
57	    ExecutorAddr Fn;
58	    WrapperFunctionBuffer ArgData;
59	    if (!SPSArgList<SPSExecutorAddr, SPSWrapperFunctionBuffer>::deserialize(
60	            IB, Fn, ArgData))
61	      return false;
62	    AA.Fn = Fn.toPtr<AllocActionFn>();
63	    AA.ArgData = std::move(ArgData);
64	    return true;
65	  }
66	};
67	
68	struct SPSAllocActionPair;
69	
70	template <> class SPSSerializationTraits<SPSAllocActionPair, AllocActionPair> {
71	public:
72	  static size_t size(const AllocActionPair &AAP) {
73	    return SPSArgList<SPSAllocAction, SPSAllocAction>::size(AAP.Finalize,
74	                                                            AAP.Dealloc);
75	  }
76	
77	  static bool serialize(SPSOutputBuffer &OB, const AllocActionPair &AAP) {
78	    return SPSArgList<SPSAllocAction, SPSAllocAction>::serialize(
79	        OB, AAP.Finalize, AAP.Dealloc);
80	  }
81	
82	  static bool deserialize(SPSInputBuffer &IB, AllocActionPair &AAP) {
83	    return SPSArgList<SPSAllocAction, SPSAllocAction>::deserialize(
84	        IB, AAP.Finalize, AAP.Dealloc);
85	  }
86	};
87	
88	struct AllocActionSPSSerializer {
89	
90	  /// Pass-through for handlers returning WrapperFunctionBuffer.
91	  static WrapperFunctionBuffer serialize(WrapperFunctionBuffer B) { return B; }
92	
93	  /// Error serialization:
94	  ///   - success values converted to empty WrapperFunctionBuffers
95	  ///   - failure values converted to out-of-band errors.
96	  static WrapperFunctionBuffer serialize(Error Err) {
97	    if (!Err)
98	      return WrapperFunctionBuffer();
99	    return WrapperFunctionBuffer::createOutOfBandError(
100	        toString(std::move(Err)).c_str());
101	  }
102	};
103	
104	template <typename... SPSArgTs> struct AllocActionSPSDeserializer {
105	  template <typename... ArgTs>
106	  bool deserialize(const char *ArgData, size_t ArgSize, ArgTs &...Args) {
107	    SPSInputBuffer IB(ArgData, ArgSize);
108	    return SPSArgList<SPSArgTs...>::deserialize(IB, Args...);
109	  }
110	};
111	
112	/// Provides call and handle utilities to simplify writing and invocation of
113	/// wrapper functions that use SimplePackedSerialization to serialize and
114	/// deserialize their arguments and return values.
115	template <typename... SPSArgTs> struct SPSAllocActionFunction {
116	
117	  template <typename Handler>
118	  static WrapperFunctionBuffer handle(const char *ArgData, size_t ArgSize,
119	                                      Handler &&H) {
120	    return AllocActionFunction::handle(
121	        ArgData, ArgSize, AllocActionSPSDeserializer<SPSTuple<SPSArgTs...>>(),
122	        AllocActionSPSSerializer(), std::forward<Handler>(H));
123	  }
124	};
125	
126	} // namespace orc_rt
127	
128	#endif // ORC_RT_SPSALLOCACTION_H
