34	static std::vector<char *>
35	makeNullTerminatedCStringArray(std::vector<std::string> &U) {
36	  std::vector<char *> V;
37	  V.reserve(U.size() + 1);
38	  for (auto &E : U)
39	    V.push_back(E.data());
40	  V.push_back(nullptr);
41	  return V;
42	}
