45	               std::vector<std::string> Args) {
46	  auto ArgV = makeNullTerminatedCStringArray(Args);
47	  // Use Args.size() below, not ArgV.size, because ArgV contains a null
48	  // terminator.
49	  Return(Main(Args.size(), ArgV.data()));
