1	//===---- SimplePackedSerialization.h - simple serialization ----*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// This file is a part of the ORC runtime support library.
10	//
11	// The behavior of the utilities in this header must be synchronized with the
12	// behavior of the utilities in
13	// llvm/ExecutionEngine/Orc/Shared/WrapperFunctionUtils.h.
14	//
15	// The Simple Packed Serialization (SPS) utilities are used to generate
16	// argument and return buffers for wrapper functions using the following
17	// serialization scheme:
18	//
19	// Primitives:
20	//   bool, char, int8_t, uint8_t -- Two's complement 8-bit (0=false, 1=true)
21	//   int16_t, uint16_t           -- Two's complement 16-bit little endian
22	//   int32_t, uint32_t           -- Two's complement 32-bit little endian
23	//   int64_t, int64_t            -- Two's complement 64-bit little endian
24	//
25	// Sequence<T>:
26	//   Serialized as the sequence length (as a uint64_t) followed by the
27	//   serialization of each of the elements without padding.
28	//
29	// Tuple<T1, ..., TN>:
30	//   Serialized as each of the element types from T1 to TN without padding.
31	//
32	//===----------------------------------------------------------------------===//
33	
34	#ifndef ORC_RT_SIMPLEPACKEDSERIALIZATION_H
35	#define ORC_RT_SIMPLEPACKEDSERIALIZATION_H
36	
37	#include "orc-rt/Error.h"
38	#include "orc-rt/ExecutorAddress.h"
39	#include "orc-rt/bit.h"
40	#include "orc-rt/iterator_range.h"
41	#include "orc-rt/span.h"
42	
43	#include <cstring>
44	#include <optional>
45	#include <string>
46	#include <string_view>
47	#include <tuple>
48	#include <type_traits>
49	#include <unordered_map>
50	#include <utility>
51	#include <variant>
52	#include <vector>
53	
54	namespace orc_rt {
55	
56	/// Output char buffer with overflow check.
57	class SPSOutputBuffer {
58	public:
59	  SPSOutputBuffer(char *Buffer, size_t Remaining)
60	      : Buffer(Buffer), Remaining(Remaining) {}
61	  bool write(const char *Data, size_t Size) {
62	    if (Size > Remaining)
63	      return false;
64	    memcpy(Buffer, Data, Size);
65	    Buffer += Size;
66	    Remaining -= Size;
67	    return true;
68	  }
69	
70	private:
71	  char *Buffer = nullptr;
72	  size_t Remaining = 0;
73	};
74	
75	/// Input char buffer with underflow check.
76	class SPSInputBuffer {
77	public:
78	  SPSInputBuffer() = default;
79	  SPSInputBuffer(const char *Buffer, size_t Remaining)
80	      : Buffer(Buffer), Remaining(Remaining) {}
81	  bool read(char *Data, size_t Size) {
82	    if (Size > Remaining)
83	      return false;
84	    memcpy(Data, Buffer, Size);
85	    Buffer += Size;
86	    Remaining -= Size;
87	    return true;
88	  }
89	
90	  const char *data() const { return Buffer; }
91	  bool skip(size_t Size) {
92	    if (Size > Remaining)
93	      return false;
94	    Buffer += Size;
95	    Remaining -= Size;
96	    return true;
97	  }
98	
99	private:
100	  const char *Buffer = nullptr;
101	  size_t Remaining = 0;
102	};
103	
104	/// Specialize to describe how to serialize/deserialize to/from the given
105	/// concrete type.
106	template <typename SPSTagT, typename ConcreteT, typename _ = void>
107	class SPSSerializationTraits;
108	
109	/// A utility class for serializing to a blob from a variadic list.
110	template <typename... ArgTs> class SPSArgList;
111	
112	// Empty list specialization for SPSArgList.
113	template <> class SPSArgList<> {
114	public:
115	  static size_t size() { return 0; }
116	
117	  static bool serialize(SPSOutputBuffer &OB) { return true; }
118	  static bool deserialize(SPSInputBuffer &IB) { return true; }
119	};
120	
121	// Non-empty list specialization for SPSArgList.
122	template <typename SPSTagT, typename... SPSTagTs>
123	class SPSArgList<SPSTagT, SPSTagTs...> {
124	public:
125	  template <typename ArgT, typename... ArgTs>
126	  static size_t size(const ArgT &Arg, const ArgTs &...Args) {
127	    return SPSSerializationTraits<SPSTagT, ArgT>::size(Arg) +
128	           SPSArgList<SPSTagTs...>::size(Args...);
129	  }
130	
131	  template <typename ArgT, typename... ArgTs>
132	  static bool serialize(SPSOutputBuffer &OB, const ArgT &Arg,
133	                        const ArgTs &...Args) {
134	    return SPSSerializationTraits<SPSTagT, ArgT>::serialize(OB, Arg) &&
135	           SPSArgList<SPSTagTs...>::serialize(OB, Args...);
136	  }
137	
138	  template <typename ArgT, typename... ArgTs>
139	  static bool deserialize(SPSInputBuffer &IB, ArgT &Arg, ArgTs &...Args) {
140	    return SPSSerializationTraits<SPSTagT, ArgT>::deserialize(IB, Arg) &&
141	           SPSArgList<SPSTagTs...>::deserialize(IB, Args...);
142	  }
143	};
144	
145	/// SPS serialization for integral types, bool, and char.
146	template <typename SPSTagT>
147	class SPSSerializationTraits<
148	    SPSTagT, SPSTagT,
149	    std::enable_if_t<std::is_same<SPSTagT, bool>::value ||
150	                     std::is_same<SPSTagT, char>::value ||
151	                     std::is_same<SPSTagT, int8_t>::value ||
152	                     std::is_same<SPSTagT, int16_t>::value ||
153	                     std::is_same<SPSTagT, int32_t>::value ||
154	                     std::is_same<SPSTagT, int64_t>::value ||
155	                     std::is_same<SPSTagT, uint8_t>::value ||
156	                     std::is_same<SPSTagT, uint16_t>::value ||
157	                     std::is_same<SPSTagT, uint32_t>::value ||
